const { run } = require('@mermaid-js/mermaid-cli');

const config = {
  theme: 'default',
  backgroundColor: '#ffffff',
  fontFamily: 'Arial, sans-serif',
  fontSize: '12px',
  flowchart: {
    curve: 'basis',
    htmlLabels: true
  }
};

run('/app/output/lakehouse_flow.mmd', '/app/output/result.png', {
  theme: 'default',
  backgroundColor: '#ffffff',
  fontFamily: 'Arial, sans-serif',
  fontSize: '12px'
}).then(() => {
  console.log('Diagram rendered successfully');
}).catch((err) => {
  console.error('Error rendering diagram:', err);
  process.exit(1);
});

